<style>
:root{--paper:var(--swe-palette-hex-faf7f2,#faf7f2);--panel:var(--swe-palette-hex-fffdf9,#fffdf9);--ink:var(--swe-palette-hex-35252a,#35252a);--muted:var(--swe-palette-hex-7e6b67,#7e6b67);--wine:var(--swe-palette-hex-641b2a,#641b2a);--gold:var(--swe-palette-hex-b78a54,#b78a54);--line:var(--swe-palette-hex-ddcfc1,#ddcfc1);--soft:var(--swe-palette-hex-f4ebe1,#f4ebe1);color-scheme:light}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;padding:40px 24px max(26px,env(safe-area-inset-bottom));min-height:100svh}main{max-width:940px;margin:auto}a{color:var(--wine);text-decoration:none}a:focus-visible,button:focus-visible{outline:2px solid var(--gold);outline-offset:4px}.brand{display:flex;align-items:center;justify-content:center;width:max-content;max-width:100%;margin:0 auto 32px;text-align:center;line-height:1.2}.brand img{display:block;height:32px;width:auto;max-width:min(180px,100%)}.brand>span{font-family:'Playfair Display',Georgia,serif;font-size:25px;letter-spacing:.18em}.brand small{display:block;font-size:8px;letter-spacing:.25em;margin-top:5px}.attendance-shell{display:grid;grid-template-columns:1fr 1.1fr;background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden;box-shadow:0 16px 60px var(--swe-palette-hex-3b202808,#3b202808)}.event-header{position:relative;isolation:isolate;overflow:hidden;background:linear-gradient(135deg,var(--swe-palette-hex-301019ed,#301019ed),var(--swe-palette-hex-641b2ae8,#641b2ae8)),url('/images/swe-home-hero.jpg') 70% center/cover;color:var(--swe-palette-hex-fff4ec,#fff4ec);padding:52px 35px;display:flex;flex-direction:column;align-items:flex-start;min-width:0}.event-header:after{content:'';width:230px;height:270px;border:1px solid var(--swe-palette-hex-edcda92a,#edcda92a);border-radius:48%;position:absolute;right:-110px;bottom:-100px;z-index:-1;transform:rotate(-22deg)}.eyebrow{font-size:8px;font-weight:600;letter-spacing:.2em;color:var(--swe-palette-hex-e6c7a2,#e6c7a2)}h1,h2{font-family:'Playfair Display',Georgia,serif;font-weight:400;letter-spacing:-.035em}h1{font-size:39px;line-height:1.15;margin:24px 0;overflow-wrap:anywhere}p{line-height:1.85;margin:0}.event-date{font-size:12px;color:var(--swe-palette-hex-f0d9cf,#f0d9cf)}.event-location{font-size:11px;color:var(--swe-palette-hex-dec2b7,#dec2b7);margin-top:12px}.event-tag{display:inline-flex;align-items:center;gap:8px;margin-top:auto;padding-top:40px;font-size:8px;letter-spacing:.12em;color:var(--swe-palette-hex-e6c7a2,#e6c7a2)}.event-tag>span{width:5px;height:5px;background:var(--swe-palette-hex-d4ad7f,#d4ad7f);border-radius:50%}.attendance-content{padding:44px 34px;min-width:0}.section-kicker{display:flex;align-items:center;gap:10px;font-size:8px;font-weight:600;letter-spacing:.17em;color:var(--muted)}.line{width:24px;height:1px;background:var(--gold)}h2{font-size:31px;line-height:1.2;margin:18px 0 14px}.intro{font-size:12px;color:var(--muted)}.visitor-welcome{margin-bottom:18px}.hours{display:flex;align-items:center;gap:9px;font-size:10px;color:var(--muted);padding:13px 0 20px}.hours svg,.notice svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.5;flex-shrink:0}.field{margin-bottom:18px}label{display:block;font-size:11px;font-weight:500;margin-bottom:7px}input{width:100%;min-width:0;border:1px solid var(--swe-palette-hex-cdb9a8,#cdb9a8);background:var(--panel);color:var(--ink);border-radius:4px;font:inherit;font-size:16px;padding:12px 13px;min-height:46px}input::placeholder{color:var(--swe-palette-hex-a28f85,#a28f85);font-size:12px}input:focus{outline:2px solid var(--gold);outline-offset:2px}input[aria-invalid=true],select[aria-invalid=true]{border-color:var(--swe-palette-hex-a34847,#a34847)}select{width:100%;min-width:0;border:1px solid var(--swe-palette-hex-cdb9a8,#cdb9a8);background:var(--panel);color:var(--ink);border-radius:4px;font:inherit;font-size:16px;padding:12px 13px;min-height:46px}select:focus{outline:2px solid var(--gold);outline-offset:2px}.field[hidden]{display:none}.error{font-size:11px;color:var(--swe-palette-hex-a34847,#a34847);margin-top:6px}button{width:100%;display:flex;align-items:center;justify-content:space-between;border:1px solid var(--wine);border-radius:4px;background:var(--wine);color:#fff;padding:14px 17px;font:inherit;font-size:12px;font-weight:500;cursor:pointer;min-height:47px;transition:background .2s}button:hover{background:var(--swe-palette-hex-4d1421,#4d1421)}button>span{font-size:19px}.notice{display:flex;gap:15px;background:var(--soft);border:1px solid var(--line);border-left:3px solid var(--gold);border-radius:5px;padding:21px 18px;margin:24px 0 16px}.notice-icon{color:var(--wine);padding-top:2px}.notice h3{font-size:12px;font-weight:600;margin:0 0 8px;color:var(--wine)}.notice p{font-size:13px}.note{font-size:11px;color:var(--muted)}.success-modal{width:min(420px,calc(100vw - 32px));max-width:100%;max-height:calc(100svh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));margin:auto;padding:0;border:1px solid var(--line);border-radius:9px;background:var(--panel);color:var(--ink);box-shadow:0 16px 60px var(--swe-palette-hex-3b202840,#3b202840);overflow:auto}.success-modal::backdrop{background:var(--swe-palette-hex-1d121680,#1d121680)}.success-card{padding:32px 22px max(22px,env(safe-area-inset-bottom));text-align:center;min-width:0}.success-modal .eyebrow{color:var(--wine)}.success-modal h2{font-size:30px;line-height:1.2;margin:14px 0 8px;overflow-wrap:anywhere}.success-modal p{font-size:14px;color:var(--muted);overflow-wrap:anywhere}.success-prizes{margin-top:18px;padding-top:16px;border-top:1px solid var(--line);text-align:left;min-width:0}.success-prizes>p{font-size:12px}.success-prizes ul{list-style:none;margin:12px 0 0;padding:0}.success-prizes li{padding:10px 0;border-top:1px solid var(--line);min-width:0}.success-prizes li:first-child{border-top:0;padding-top:0}.success-prizes strong{display:block;font-size:13px;font-weight:600;color:var(--ink);overflow-wrap:anywhere}.success-prizes span,.success-prizes em{display:block;margin-top:4px;font-size:11px;font-style:normal;color:var(--muted);overflow-wrap:anywhere}.success-prize-terms{margin-top:12px;font-size:11px;white-space:pre-line}.content-footer{display:flex;flex-wrap:wrap;gap:15px;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:22px;margin-top:30px}.content-footer>span{font-size:7px;letter-spacing:.14em;color:var(--muted)}.content-footer a{font-size:10px}footer{text-align:center;color:var(--muted);font-size:10px;padding-top:25px;line-height:1.9}footer a{display:block;font-size:9px;margin-top:7px}
html[data-color-theme=dark]{--paper:var(--swe-palette-hex-1d1719,#1d1719);--panel:var(--swe-palette-hex-2b2226,#2b2226);--ink:var(--swe-palette-hex-efdfd6,#efdfd6);--muted:var(--swe-palette-hex-c4afa6,#c4afa6);--wine:var(--swe-palette-hex-e8bf8f,#e8bf8f);--line:var(--swe-palette-hex-514047,#514047);--soft:var(--swe-palette-hex-36292f,#36292f);color-scheme:dark}html[data-color-theme=dark] button{background:var(--swe-palette-hex-641b2a,#641b2a);border-color:var(--swe-palette-hex-9a5263,#9a5263)}html[data-color-theme=dark] button:hover{background:var(--swe-palette-hex-782d3d,#782d3d)}
html[data-color-theme=dark] .error{color:var(--swe-palette-hex-e2aaa0,#e2aaa0)}html[data-color-theme=dark] input[aria-invalid=true]{border-color:var(--swe-palette-hex-bd8581,#bd8581)}
.visitor-prizes{margin:23px 0;padding:21px 18px;background:var(--soft);border:1px solid var(--line);border-radius:5px}.visitor-prizes>.eyebrow{color:var(--wine);font-size:7px}.visitor-prizes h3{font-family:'Playfair Display',Georgia,serif;color:var(--ink);font-size:23px;line-height:1.3;font-weight:400;letter-spacing:-.02em;margin:12px 0}.visitor-prizes>p{font-size:11px;color:var(--muted)}.visitor-prizes ul{list-style:none;padding:0;margin:17px 0 0}.visitor-prizes li{display:flex;align-items:flex-start;gap:10px;padding:13px 0;border-top:1px solid var(--line);font-size:12px}.prize-mark{color:var(--gold);padding-top:1px}.visitor-prizes li>div{flex:1;min-width:0;overflow-wrap:anywhere}.visitor-prizes li strong{font-weight:600}.visitor-prizes li p{font-size:10px;color:var(--muted);margin-top:5px}.prize-quantity{color:var(--wine);font-size:9px;white-space:nowrap;padding-top:2px}.prize-terms{border-top:1px solid var(--line);padding-top:14px;margin-top:4px;font-size:10px}.prize-terms strong{color:var(--wine);font-weight:500}.prize-terms p{margin-top:6px;white-space:pre-line;overflow-wrap:anywhere;color:var(--muted)}
